use serde_json::{Value,json};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-part-ready175";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){assert_eq!(read(r("native/result.json"))["status"],"complete");let m=read("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-29-balanced-kh-adoption/artifacts/production-source-manifest.json");let mut exact=0;let mut field=0;for(f,h)in m["source_files_sha256"].as_object().unwrap(){if hash(r("source").join(f))==h.as_str().unwrap(){exact+=1}else{assert_eq!(f,"crates/zopro-core/src/msm_affine/g2_phi.rs");}if f.starts_with("crates/zopro-bn254/"){assert_eq!(hash(r("source").join(f)),h.as_str().unwrap());field+=1;}}assert_eq!(exact,174);assert_eq!(field,17);
let edit=read(r("source-audit.json"));let s=fs::read_to_string(r("source").join(edit["changed_file"].as_str().unwrap())).unwrap();let back=s.replacen(edit["after"].as_str().unwrap(),edit["before"].as_str().unwrap(),1).replacen(edit["module_declaration"].as_str().unwrap(),"",1);assert_eq!(format!("{:x}",Sha256::digest(back.as_bytes())),m["source_files_sha256"][edit["changed_file"].as_str().unwrap()]);assert_eq!(hash(r("part_ready.rs")),hash(r("source/crates/zopro-core/src/msm_affine/g2_phi/part_ready.rs")));
for mode in["off","on"]{for (suite,count) in [("core",127),("prover",8)]{let t=read(r(format!("native/{suite}-{mode}/tests.json")));assert_eq!(t["passed_tests"].as_array().unwrap().len(),count);assert_eq!(t["unfiltered"],true);}}
let binary=r("native/candidate-sdk");let bytes=fs::read(&binary).unwrap();let needle=b"ZOPRO_CPU_PHI_PART_READY";assert!(bytes.windows(needle.len()).any(|w|w==needle));let out=Command::new("nm").args(["-S","--size-sort","--defined-only"]).arg(&binary).output().unwrap();assert!(out.status.success());let text=String::from_utf8(out.stdout).unwrap();fs::create_dir(r("codegen")).unwrap();fs::write(r("codegen/symbols.txt"),&text).unwrap();let mut selected=vec![];for line in text.lines().filter(|l|l.contains("g2_phi")&&(l.contains("hb_raw")||l.contains("part_ready")&&l.contains("3raw"))){let f:Vec<_>=line.split_whitespace().collect();assert_eq!(f.len(),4);let out=Command::new("objdump").args(["-d","--no-show-raw-insn"]).arg(format!("--disassemble={}",f[3])).arg(&binary).output().unwrap();assert!(out.status.success());let to=r(format!("codegen/body-{}.asm",selected.len()));fs::write(&to,out.stdout).unwrap();selected.push(json!({"nm":line,"assembly":to,"sha256":hash(&to)}));}assert!(selected.iter().any(|s|s["nm"].as_str().unwrap().contains("hb_raw")));assert!(selected.iter().any(|s|s["nm"].as_str().unwrap().contains("part_ready")));
let v=json!({"originals":175,"candidate_files":176,"originals_exact":exact,"inverse175":true,"field_files_exact":field,"field_tests":33,"field_tests_status":"inherited","core_tests_each_mode":127,"prover_tests_each_mode":8,"linked_paths":selected,"SDK_sha256":hash(binary),"selector_present":true,"checked_memory_fit_and_oracle_passed_both_modes":true,"arithmetic_binary_identity_claimed":false,"production_changed":false});fs::write(r("code-audit.json"),serde_json::to_vec_pretty(&v).unwrap()).unwrap();println!("174 exact+1 dispatch+1 child; inverse175;17field exact;127core/8prover each OFF/ON; both SDK paths present");}
